mapper.select:
SELECT id, name, display_order, is_visible
FROM info_categories
WHERE id = #{id}

mapper.update:
UPDATE info_categories
SET name = #{name},
    display_order = #{displayOrder},
    is_visible = #{isVisible}
WHERE id = #{id}

mapper.select:
SELECT COUNT(*)
FROM info_categories
WHERE name = #{name}

    AND id <> #{excludeId}

SELECT COUNT(*)
FROM travel_info
WHERE category_id = #{categoryId}
